// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed parameters: actor will call initialize and nftArg is the intended nft address
    function testFuzz_property(address actor, address nftArg, uint128 virtBase, uint128 virtNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        // keep wide but avoid trivial zero-address collisions for actor equality checks
        vm.assume(actor != address(0));

        // call initialize as actor so msg.sender == actor
        vm.prank(actor);
        bool ok;
        try c.initialize(address(0), nftArg, virtBase, virtNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: if initialize succeeded, c.nft() must equal the nft argument passed (nftArg).
        // Mutant sets nft = msg.sender, so when actor != nftArg and initialize succeeds, mutant will violate this.
        if (ok) {
            assertTrue(c.nft() == nftArg);
        } else {
            // if initialize reverted, we cannot assert nft; in that case we just assert that initialize indeed reverted
            // but to keep exactly one assertion overall, we still use the same assertTrue by encoding the allowed case:
            // When initialize reverts, require that nft wasn't set to something else can't be checked — treat revert as acceptable path
            // So we assert that either init succeeded and nft equals nftArg, or init reverted (ok==false) which is allowed.
            // To keep a single assertTrue reading c, use nft getter: if init reverted then nft remains default 0 and nftArg may be 0.
            // We therefore assert ok || c.nft() == nftArg
            assertTrue(ok || c.nft() == nftArg);
        }
    }
}

